CREATE TABLE f_new (id Uint64 NOT NULL, n Int64, PRIMARY KEY (id));
INSERT INTO f_new (id, n) SELECT id, CAST(n AS Int64) AS n FROM f;
ALTER TABLE f DROP CHANGEFEED updates;
ALTER TABLE f RENAME TO f_old;
ALTER TABLE f_new RENAME TO f;
ALTER TABLE f ADD CHANGEFEED updates WITH (MODE = 'UPDATES', FORMAT = 'JSON');
ALTER TOPIC `f/updates` ADD CONSUMER audit WITH (important = TRUE);
DROP TABLE f_old;
CREATE TABLE g_new (id Uint64 NOT NULL, v Utf8, PRIMARY KEY (id), INDEX by_v GLOBAL ON (v));
ALTER TABLE g_new ALTER INDEX by_v SET (AUTO_PARTITIONING_MIN_PARTITIONS_COUNT = 2);
INSERT INTO g_new (id, v) SELECT id, v FROM g;
ALTER TABLE g RENAME TO g_old;
ALTER TABLE g_new RENAME TO g;
DROP TABLE g_old;
CREATE TABLE h_new (id Uint64 NOT NULL, v Utf8, PRIMARY KEY (id));
INSERT INTO h_new (id, v) SELECT id, v FROM h;
